def is_mirrored(code):
    left, right = 0, len(code) - 1
    while left < right:
        if not code[left].isalnum():
            left += 1
        elif not code[right].isalnum():
            right -= 1
        elif code[left].lower() != code[right].lower():
            return False
        else:
            left += 1
            right -= 1
    return True
